-- Execute only after all 12 WebP are live at manualdecocina.com with exact manifest hashes.
-- New group, seven languages; abort atomically on any identity or route collision.
DO $patacones$
DECLARE
 j constant jsonb := $records$[{"id":"1eaeabf2-79b1-5a42-9736-ba2a9348b501","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"es","slug":"patacones-con-hogao","public_path":"/patacones-con-hogao","source_url":null,"source_post_id":null,"title":"Patacones con hogao colombianos","excerpt":"Patacones de plátano verde con doble fritura y hogao casero de tomate y cebolla larga; crujientes y listos para compartir.","summary":"Los patacones se fríen una vez para ablandar el plátano verde, se aplastan y vuelven al aceite hasta dorarse. El hogao de tomate y cebolla larga se sirve tibio aparte para mantener su textura crujiente.","notes":"Usa plátanos verdes firmes, sin manchas amarillas. Controla el aceite con termómetro y fríe en tandas para que no baje bruscamente la temperatura. Seca las piezas antes de meterlas en el aceite; el agua salpica. No dejes la sartén sin vigilancia. El aceite de fritura utilizado no se consume entero: la nutrición estima 60 g absorbidos en las 12 piezas, sin medición física. Refrigera los patacones y el hogao por separado dentro de 2 horas, hasta 3 días; recalienta los discos en horno a 200 °C y el hogao aparte. El plato no incluye lácteos ni gluten en esta formulación, pero verifica contaminación cruzada y etiquetas del aceite si hay alergias.","content_html":"<p>Los patacones se fríen una vez para ablandar el plátano verde, se aplastan y vuelven al aceite hasta dorarse. El hogao de tomate y cebolla larga se sirve tibio aparte para mantener su textura crujiente.</p><p>Usa plátanos verdes firmes, sin manchas amarillas. Controla el aceite con termómetro y fríe en tandas para que no baje bruscamente la temperatura. Seca las piezas antes de meterlas en el aceite; el agua salpica. No dejes la sartén sin vigilancia. El aceite de fritura utilizado no se consume entero: la nutrición estima 60 g absorbidos en las 12 piezas, sin medición física. Refrigera los patacones y el hogao por separado dentro de 2 horas, hasta 3 días; recalienta los discos en horno a 200 °C y el hogao aparte. El plato no incluye lácteos ni gluten en esta formulación, pero verifica contaminación cruzada y etiquetas del aceite si hay alergias.</p>","ingredients":[{"name":"plátanos bien verdes (aprox. 600 g de pulpa pelada)","amount":"3","unit":"unidades","group":"Para los patacones"},{"name":"aceite de canola para freír (no se consume entero)","amount":"750","unit":"ml","group":"Para los patacones"},{"name":"tomates maduros","amount":"300","unit":"g","group":"Para el hogao"},{"name":"cebolla larga","amount":"120","unit":"g","group":"Para el hogao"},{"name":"ajo","amount":"12","unit":"g","group":"Para el hogao"},{"name":"aceite de canola","amount":"15","unit":"g","group":"Para el hogao"},{"name":"sal fina total","amount":"6","unit":"g","group":"Para ambos"}],"steps":[{"title":"Pela y corta el plátano","content":"Pela 3 plátanos bien verdes y corta cada uno en 4 trozos transversales de unos 4 cm. Debes obtener 12 piezas.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Patacones con hogao: pela y corta el plátano"},{"title":"Pica las verduras","content":"Pica finamente 300 g de tomate, 120 g de cebolla larga y 12 g de ajo; mantenlos separados.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Patacones con hogao: pica las verduras"},{"title":"Sofríe la cebolla","content":"Calienta 15 g de aceite de canola en una sartén a fuego medio-bajo. Cocina la cebolla larga y el ajo durante 3 minutos sin dorarlos.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Patacones con hogao: sofríe la cebolla"},{"title":"Reduce el hogao","content":"Añade el tomate y 2 g de sal. Cocina a fuego bajo de 12 a 15 minutos, removiendo, hasta que el tomate se deshaga y la salsa espese.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Patacones con hogao: reduce el hogao"},{"title":"Fríe los trozos una vez","content":"Calienta suficiente aceite de canola para cubrir 2 a 3 cm de una sartén honda, a unos 165–170 °C. Fríe los trozos en tandas durante 4 a 5 minutos, hasta que se ablanden sin dorarse del todo. Escúrrelos.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Patacones con hogao: fríe los trozos una vez"},{"title":"Aplasta los plátanos","content":"Deja templar las piezas 2 minutos. Prensa cada una entre dos hojas de papel de horno hasta formar un disco de unos 8 mm; evita que se rompa.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Patacones con hogao: aplasta los plátanos"},{"title":"Fríe los discos de nuevo","content":"Sube el aceite a unos 175–180 °C. Fríe los discos en tandas de 2 a 3 minutos por lado, hasta que queden dorados y crujientes. Escúrrelos y espolvorea los 4 g de sal restantes.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Patacones con hogao: fríe los discos de nuevo"},{"title":"Sirve con hogao","content":"Reparte 3 patacones calientes por persona y lleva el hogao tibio en un cuenco aparte; añade la salsa justo antes de cada bocado para conservar el crujiente.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Patacones con hogao: sirve con hogao"}],"category":"Entrantes y aperitivos","course":"Entrada","cuisine":"Colombiana","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Patacones dorados con hogao de tomate y cebolla larga servido aparte"}],"video_urls":[],"keywords":["patacones con hogao","patacones colombianos","plátano verde frito","hogao colombiano"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 patacones con 1/4 del hogao","method":"sum(valor por 100 g × gramos / 100) / 4; 600 g de pulpa de plátano verde, 300 g de tomate, 120 g de cebolla larga, 12 g de ajo, 15 g de aceite del hogao, 60 g de aceite de fritura absorbido (hipótesis no medida) y 6 g de sal","note":"Estimación por formulación. La pulpa pelada y el aceite absorbido deben pesarse en una prueba física; el valor real por ración puede variar bastante."},"seo":{"title":"Patacones con hogao: receta colombiana crujiente | Manual de Cocina","description":"Cómo hacer patacones con hogao casero: plátano verde con doble fritura, salsa de tomate y cebolla larga, ocho pasos y consejos para servir crujientes.","image_alt":"Patacones colombianos crujientes con hogao de tomate y cebolla larga","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"¿Por qué los patacones se fríen dos veces?","a":"La primera fritura ablanda el plátano para poder aplanarlo; la segunda dora el disco y lo deja crujiente."},{"q":"¿Se puede usar plátano maduro?","a":"Para esta textura se necesita plátano bien verde. El maduro se ablanda y endulza al freírse y no produce el mismo patacón."},{"q":"¿Cómo evito que se rompan al aplastarlos?","a":"Aplástalos mientras siguen tibios, entre dos hojas de papel de horno, con presión gradual y sin dejarlos demasiado finos."},{"q":"¿Cuándo se pone el hogao?","a":"Sírvelo tibio aparte o agrégalo al momento de comer. Si lo dejas encima mucho tiempo, el patacón pierde crocancia."},{"q":"¿Cómo se guardan y recalientan?","a":"Refrigera el hogao y los patacones por separado en recipientes cerrados hasta 3 días. Recalienta los discos en horno a 200 °C hasta que estén calientes y crujientes; calienta el hogao aparte."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"6eb51a3b-6f29-5f76-a7ba-9a02c3fcb9ee","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"de","slug":"kolumbianische-patacones-mit-hogao","public_path":"/de/kolumbianische-patacones-mit-hogao","source_url":null,"source_post_id":null,"title":"Kolumbianische Patacones mit Hogao","excerpt":"Zweimal frittierte grüne Kochbananen mit warmer kolumbianischer Tomaten-Frühlingszwiebel-Sauce.","summary":"Grüne Kochbananen werden zunächst weich frittiert, flach gedrückt und ein zweites Mal knusprig ausgebacken. Die warme Sauce aus Tomaten und Frühlingszwiebeln separat reichen, damit die Patacones kross bleiben.","notes":"Feste, vollständig grüne Kochbananen verwenden. Die Stücke vor dem Frittieren abtrocknen, damit das Öl weniger spritzt. Mit Thermometer arbeiten, portionsweise frittieren und heißes Öl nie unbeaufsichtigt lassen. Die gesamte Menge Frittieröl wird nicht verzehrt; für die Nährwerte werden 60 g aufgenommenes Öl für alle 12 Patacones angenommen, ohne Messung. Sauce und Patacones innerhalb von 2 Stunden getrennt in den Kühlschrank stellen und bis zu 3 Tage aufbewahren. Die Scheiben bei 200 °C im Ofen, die Sauce separat erhitzen. Diese Rezeptur enthält keine Milch- oder glutenhaltigen Zutaten; bei Allergien Etiketten und Kreuzkontakt prüfen.","content_html":"<p>Grüne Kochbananen werden zunächst weich frittiert, flach gedrückt und ein zweites Mal knusprig ausgebacken. Die warme Sauce aus Tomaten und Frühlingszwiebeln separat reichen, damit die Patacones kross bleiben.</p><p>Feste, vollständig grüne Kochbananen verwenden. Die Stücke vor dem Frittieren abtrocknen, damit das Öl weniger spritzt. Mit Thermometer arbeiten, portionsweise frittieren und heißes Öl nie unbeaufsichtigt lassen. Die gesamte Menge Frittieröl wird nicht verzehrt; für die Nährwerte werden 60 g aufgenommenes Öl für alle 12 Patacones angenommen, ohne Messung. Sauce und Patacones innerhalb von 2 Stunden getrennt in den Kühlschrank stellen und bis zu 3 Tage aufbewahren. Die Scheiben bei 200 °C im Ofen, die Sauce separat erhitzen. Diese Rezeptur enthält keine Milch- oder glutenhaltigen Zutaten; bei Allergien Etiketten und Kreuzkontakt prüfen.</p>","ingredients":[{"name":"feste grüne Kochbananen (etwa 600 g geschältes Fruchtfleisch)","amount":"3","unit":"Stück","group":"Für die Patacones"},{"name":"Rapsöl zum Frittieren (wird nicht vollständig verzehrt)","amount":"750","unit":"ml","group":"Für die Patacones"},{"name":"reife Tomaten","amount":"300","unit":"g","group":"Für den Hogao"},{"name":"Frühlingszwiebeln","amount":"120","unit":"g","group":"Für den Hogao"},{"name":"Knoblauch","amount":"12","unit":"g","group":"Für den Hogao"},{"name":"Rapsöl","amount":"15","unit":"g","group":"Für den Hogao"},{"name":"feines Salz, aufgeteilt","amount":"6","unit":"g","group":"Für beides"}],"steps":[{"title":"Kochbananen schälen und schneiden","content":"3 vollständig grüne Kochbananen schälen und jede quer in 4 Stücke von etwa 4 cm Länge schneiden; es sollen 12 Stücke entstehen.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Kolumbianische Patacones mit Hogao: Kochbananen schälen und schneiden"},{"title":"Gemüse fein schneiden","content":"300 g Tomaten, 120 g Frühlingszwiebeln und 12 g Knoblauch fein schneiden und getrennt bereithalten.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Kolumbianische Patacones mit Hogao: Gemüse fein schneiden"},{"title":"Frühlingszwiebeln anschwitzen","content":"15 g Rapsöl in einer Pfanne bei mittlerer bis niedriger Hitze erwärmen. Frühlingszwiebeln und Knoblauch 3 Minuten garen, ohne sie zu bräunen.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Kolumbianische Patacones mit Hogao: Frühlingszwiebeln anschwitzen"},{"title":"Hogao einkochen","content":"Tomaten und 2 g Salz zugeben. Bei niedriger Hitze 12–15 Minuten unter Rühren garen, bis die Tomaten zerfallen und die Sauce eindickt.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Kolumbianische Patacones mit Hogao: Hogao einkochen"},{"title":"Stücke ein erstes Mal frittieren","content":"Rapsöl in einer tiefen Pfanne 2–3 cm hoch auf etwa 165–170 °C erhitzen. Die Stücke portionsweise 4–5 Minuten frittieren, bis sie weich, aber noch nicht ganz gebräunt sind. Abtropfen lassen.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Kolumbianische Patacones mit Hogao: Stücke ein erstes Mal frittieren"},{"title":"Kochbananen flach drücken","content":"Die Stücke 2 Minuten abkühlen lassen. Jedes zwischen zwei Bögen Backpapier vorsichtig zu einer etwa 8 mm dicken Scheibe pressen, ohne es zu zerbrechen.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Kolumbianische Patacones mit Hogao: Kochbananen flach drücken"},{"title":"Scheiben ein zweites Mal frittieren","content":"Das Öl auf etwa 175–180 °C erhitzen. Die Scheiben portionsweise 2–3 Minuten pro Seite goldbraun und knusprig frittieren. Abtropfen lassen und mit den übrigen 4 g Salz bestreuen.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Kolumbianische Patacones mit Hogao: Scheiben ein zweites Mal frittieren"},{"title":"Mit Hogao servieren","content":"Pro Person 3 heiße Patacones und den warmen Hogao in einer separaten Schale servieren. Sauce erst unmittelbar vor dem Essen daraufgeben.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Kolumbianische Patacones mit Hogao: Mit Hogao servieren"}],"category":"Vorspeisen und Snacks","course":"Vorspeise","cuisine":"Kolumbianisch","difficulty":"Einfach","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Kolumbianische Patacones mit Hogao"}],"video_urls":[],"keywords":["Patacones mit Hogao","kolumbianische Patacones","frittierte grüne Kochbananen","kolumbianische Tomatensauce"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 Patacones mit einem Viertel des Hogaos","method":"Nährwerte je 100 g mal Zutatengewicht / 100, geteilt durch vier; angenommen: 600 g geschälte grüne Kochbanane, 300 g Tomaten, 120 g Frühlingszwiebeln, 12 g Knoblauch, 15 g Öl in der Sauce, 60 g aufgenommenes Frittieröl und 6 g Salz.","note":"Schätzung nach Rezeptur. Geschältes Fruchtfleisch und tatsächlich aufgenommenes Öl müssen bei einem Kochtest gewogen werden; die Werte pro Portion können deutlich abweichen."},"seo":{"title":"Kolumbianische Patacones mit Hogao | Manual de Cocina","description":"Kolumbianische Patacones mit Hogao: grüne Kochbananen zweimal frittieren und mit Tomaten-Frühlingszwiebel-Sauce servieren. Acht bebilderte Schritte.","image_alt":"Kolumbianische Patacones mit Hogao","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"Warum werden Patacones zweimal frittiert?","a":"Beim ersten Frittieren werden die Kochbananen weich genug zum Flachdrücken; das zweite Frittieren macht die Scheiben goldbraun und knusprig."},{"q":"Kann ich reife Kochbananen nehmen?","a":"Für diese Textur sind vollständig grüne Kochbananen nötig. Reife werden beim Frittieren weich und süß."},{"q":"Wie verhindere ich, dass sie beim Pressen brechen?","a":"Noch warme Stücke zwischen Backpapier mit gleichmäßig zunehmendem Druck zu etwa 8 mm dicken Scheiben pressen."},{"q":"Wann kommt der Hogao auf die Patacones?","a":"Die warme Sauce separat reichen oder erst direkt vor dem Essen daraufgeben, sonst weichen die Scheiben auf."},{"q":"Wie bewahre ich Reste auf und wärme sie auf?","a":"Hogao und Patacones getrennt in geschlossenen Behältern bis zu 3 Tage kühlen. Die Scheiben bei 200 °C im Ofen knusprig erhitzen, die Sauce separat."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"7bee03ac-6d09-58f6-a3e4-12265cdfd0c9","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"en","slug":"colombian-patacones-with-hogao","public_path":"/en/colombian-patacones-with-hogao","source_url":null,"source_post_id":null,"title":"Colombian patacones with hogao","excerpt":"Twice-fried green plantain rounds with a warm Colombian tomato and scallion sauce. Crisp patacones to share.","summary":"Green plantains are fried until tender, flattened, then fried again until crisp. Serve the tomato and scallion hogao warm on the side so each patacón stays crunchy.","notes":"Choose firm, fully green plantains. Dry the pieces before frying to limit splattering. Use a thermometer, fry in batches and never leave hot oil unattended. The full volume of frying oil is not eaten: the nutrition estimate assumes 60 g retained by all 12 patacones, which has not been measured. Refrigerate the sauce and patacones separately within 2 hours for up to 3 days. Reheat the rounds in a 200 °C oven and warm the sauce separately. This formulation contains no dairy or gluten ingredients; check labels and cross-contact if you have allergies.","content_html":"<p>Green plantains are fried until tender, flattened, then fried again until crisp. Serve the tomato and scallion hogao warm on the side so each patacón stays crunchy.</p><p>Choose firm, fully green plantains. Dry the pieces before frying to limit splattering. Use a thermometer, fry in batches and never leave hot oil unattended. The full volume of frying oil is not eaten: the nutrition estimate assumes 60 g retained by all 12 patacones, which has not been measured. Refrigerate the sauce and patacones separately within 2 hours for up to 3 days. Reheat the rounds in a 200 °C oven and warm the sauce separately. This formulation contains no dairy or gluten ingredients; check labels and cross-contact if you have allergies.</p>","ingredients":[{"name":"firm green plantains (about 600 g peeled flesh)","amount":"3","unit":"","group":"For the patacones"},{"name":"canola oil for frying (not all consumed)","amount":"750","unit":"ml","group":"For the patacones"},{"name":"ripe tomatoes","amount":"300","unit":"g","group":"For the hogao"},{"name":"scallions","amount":"120","unit":"g","group":"For the hogao"},{"name":"garlic","amount":"12","unit":"g","group":"For the hogao"},{"name":"canola oil","amount":"15","unit":"g","group":"For the hogao"},{"name":"fine salt, divided","amount":"6","unit":"g","group":"For both"}],"steps":[{"title":"Peel and cut the plantains","content":"Peel 3 fully green plantains and cut each crosswise into 4 pieces about 4 cm long, making 12 pieces.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Colombian patacones with hogao: Peel and cut the plantains"},{"title":"Chop the vegetables","content":"Finely chop 300 g tomatoes, 120 g scallions and 12 g garlic; keep them separate.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Colombian patacones with hogao: Chop the vegetables"},{"title":"Soften the scallions","content":"Heat 15 g canola oil in a pan over medium-low heat. Cook the scallions and garlic for 3 minutes without browning.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Colombian patacones with hogao: Soften the scallions"},{"title":"Simmer the hogao","content":"Add the tomatoes and 2 g salt. Cook over low heat for 12–15 minutes, stirring, until the tomatoes break down and the sauce thickens.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Colombian patacones with hogao: Simmer the hogao"},{"title":"Fry the pieces once","content":"Heat enough canola oil to reach 2–3 cm in a deep pan to about 165–170 °C. Fry the pieces in batches for 4–5 minutes until tender but not fully browned. Drain.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Colombian patacones with hogao: Fry the pieces once"},{"title":"Flatten the plantains","content":"Let the pieces cool for 2 minutes. Press each one between two sheets of baking parchment into a disc about 8 mm thick without breaking it.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Colombian patacones with hogao: Flatten the plantains"},{"title":"Fry the discs again","content":"Raise the oil temperature to about 175–180 °C. Fry the discs in batches for 2–3 minutes per side until golden and crisp. Drain and sprinkle with the remaining 4 g salt.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Colombian patacones with hogao: Fry the discs again"},{"title":"Serve with hogao","content":"Serve 3 hot patacones per person with warm hogao in a separate bowl. Spoon it on just before each bite to preserve the crunch.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Colombian patacones with hogao: Serve with hogao"}],"category":"Starters and appetizers","course":"Starter","cuisine":"Colombian","difficulty":"Easy","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Colombian patacones with hogao"}],"video_urls":[],"keywords":["patacones with hogao","Colombian patacones","fried green plantains","Colombian tomato sauce"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 patacones with one-quarter of the hogao","method":"Sum of per-100-g nutrients × ingredient weights / 100, divided by four; assumes 600 g peeled green plantain, 300 g tomatoes, 120 g scallions, 12 g garlic, 15 g oil in the hogao, 60 g frying oil retained and 6 g salt.","note":"Formulation estimate. Peeled plantain weight and oil uptake require measurement in a physical test; actual values per serving may vary substantially."},"seo":{"title":"Colombian patacones with hogao | Manual de Cocina","description":"Make Colombian patacones with hogao: twice-fried green plantains and a slow-cooked tomato and scallion sauce, with eight illustrated steps.","image_alt":"Colombian patacones with hogao","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"Why fry patacones twice?","a":"The first fry softens the plantain so it can be flattened; the second browns and crisps the disc."},{"q":"Can I use ripe plantains?","a":"Use fully green plantains for this texture. Ripe ones soften and sweeten during frying and will not make the same patacón."},{"q":"How do I stop them breaking when flattened?","a":"Press them while still warm between baking parchment, applying pressure gradually and leaving the discs about 8 mm thick."},{"q":"When should I add the hogao?","a":"Serve it warm on the side or add it just before eating. Leaving it on top makes the patacones soggy."},{"q":"How do I store and reheat leftovers?","a":"Refrigerate the hogao and patacones separately in sealed containers for up to 3 days. Reheat the discs in a 200 °C oven until hot and crisp; warm the hogao separately."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"9b37649b-4b86-5495-9cff-2403c899c540","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"fr","slug":"patacones-colombiens-au-hogao","public_path":"/fr/patacones-colombiens-au-hogao","source_url":null,"source_post_id":null,"title":"Patacones colombiens au hogao","excerpt":"Des rondelles de banane plantain verte frites deux fois, avec une sauce colombienne tiède aux tomates et aux cébettes.","summary":"On frit les bananes plantains vertes une première fois pour les attendrir, on les aplatit, puis on les frit de nouveau jusqu’à ce qu’elles soient croustillantes. Le hogao de tomates et de cébettes se sert tiède à part.","notes":"Choisissez des bananes plantains fermes et entièrement vertes. Séchez les morceaux avant de les plonger dans l’huile pour limiter les projections. Contrôlez la température avec un thermomètre, procédez par petites fournées et ne laissez jamais l’huile chaude sans surveillance. Toute l’huile de friture n’est pas consommée : l’estimation nutritionnelle suppose que les 12 patacones en retiennent 60 g, quantité non mesurée. Réfrigérez sauce et patacones séparément dans les 2 heures et conservez-les jusqu’à 3 jours. Réchauffez les galettes au four à 200 °C et la sauce à part. Cette recette ne contient pas d’ingrédients laitiers ou avec gluten ; en cas d’allergie, vérifiez les étiquettes et les contaminations croisées.","content_html":"<p>On frit les bananes plantains vertes une première fois pour les attendrir, on les aplatit, puis on les frit de nouveau jusqu’à ce qu’elles soient croustillantes. Le hogao de tomates et de cébettes se sert tiède à part.</p><p>Choisissez des bananes plantains fermes et entièrement vertes. Séchez les morceaux avant de les plonger dans l’huile pour limiter les projections. Contrôlez la température avec un thermomètre, procédez par petites fournées et ne laissez jamais l’huile chaude sans surveillance. Toute l’huile de friture n’est pas consommée : l’estimation nutritionnelle suppose que les 12 patacones en retiennent 60 g, quantité non mesurée. Réfrigérez sauce et patacones séparément dans les 2 heures et conservez-les jusqu’à 3 jours. Réchauffez les galettes au four à 200 °C et la sauce à part. Cette recette ne contient pas d’ingrédients laitiers ou avec gluten ; en cas d’allergie, vérifiez les étiquettes et les contaminations croisées.</p>","ingredients":[{"name":"bananes plantains fermes et vertes (environ 600 g de chair épluchée)","amount":"3","unit":"","group":"Pour les patacones"},{"name":"huile de colza pour la friture (non consommée en totalité)","amount":"750","unit":"ml","group":"Pour les patacones"},{"name":"tomates mûres","amount":"300","unit":"g","group":"Pour le hogao"},{"name":"cébettes","amount":"120","unit":"g","group":"Pour le hogao"},{"name":"ail","amount":"12","unit":"g","group":"Pour le hogao"},{"name":"huile de colza","amount":"15","unit":"g","group":"Pour le hogao"},{"name":"sel fin, réparti","amount":"6","unit":"g","group":"Pour les deux"}],"steps":[{"title":"Éplucher et couper les plantains","content":"Épluchez 3 bananes plantains bien vertes et coupez chacune en 4 tronçons de 4 cm environ, soit 12 morceaux.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Patacones colombiens au hogao: Éplucher et couper les plantains"},{"title":"Émincer les légumes","content":"Hachez finement 300 g de tomates, 120 g de cébettes et 12 g d’ail ; gardez-les séparés.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Patacones colombiens au hogao: Émincer les légumes"},{"title":"Faire revenir les cébettes","content":"Faites chauffer 15 g d’huile de colza dans une poêle à feu moyen-doux. Faites cuire les cébettes et l’ail pendant 3 minutes sans les colorer.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Patacones colombiens au hogao: Faire revenir les cébettes"},{"title":"Faire réduire le hogao","content":"Ajoutez les tomates et 2 g de sel. Laissez mijoter 12 à 15 minutes à feu doux en remuant, jusqu’à ce que les tomates se défassent et que la sauce épaississe.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Patacones colombiens au hogao: Faire réduire le hogao"},{"title":"Faire une première friture","content":"Faites chauffer 2 à 3 cm d’huile de colza dans une poêle profonde à environ 165–170 °C. Faites frire les morceaux par petites fournées pendant 4 à 5 minutes, jusqu’à ce qu’ils soient tendres mais peu colorés. Égouttez.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Patacones colombiens au hogao: Faire une première friture"},{"title":"Aplatir les plantains","content":"Laissez tiédir les morceaux 2 minutes. Pressez-les un à un entre deux feuilles de papier cuisson pour obtenir des disques d’environ 8 mm, sans les casser.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Patacones colombiens au hogao: Aplatir les plantains"},{"title":"Faire une seconde friture","content":"Montez l’huile à environ 175–180 °C. Faites frire les disques par fournées 2 à 3 minutes de chaque côté, jusqu’à ce qu’ils soient dorés et croustillants. Égouttez et parsemez des 4 g de sel restants.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Patacones colombiens au hogao: Faire une seconde friture"},{"title":"Servir avec le hogao","content":"Servez 3 patacones chauds par personne avec le hogao tiède dans un bol à part. Ajoutez la sauce juste avant de croquer pour garder le croustillant.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Patacones colombiens au hogao: Servir avec le hogao"}],"category":"Entrées et apéritifs","course":"Entrée","cuisine":"Colombienne","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Patacones colombiens au hogao"}],"video_urls":[],"keywords":["patacones au hogao","patacones colombiens","banane plantain verte frite","sauce colombienne aux tomates"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 patacones avec un quart du hogao","method":"Somme des nutriments pour 100 g × poids des ingrédients / 100, divisée par quatre ; hypothèses : 600 g de chair de plantain vert, 300 g de tomates, 120 g de cébettes, 12 g d’ail, 15 g d’huile dans le hogao, 60 g d’huile de friture absorbée et 6 g de sel.","note":"Estimation fondée sur la recette. Le poids de chair épluchée et l’huile absorbée doivent être mesurés lors d’un essai réel ; les valeurs par portion peuvent varier sensiblement."},"seo":{"title":"Patacones colombiens au hogao | Manual de Cocina","description":"Préparez des patacones colombiens au hogao : plantains verts frits deux fois, sauce tomate et cébettes, huit étapes illustrées.","image_alt":"Patacones colombiens au hogao","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"Pourquoi cuire les patacones en deux fritures ?","a":"La première cuisson attendrit le plantain pour pouvoir l’aplatir ; la seconde dore et rend le disque croustillant."},{"q":"Peut-on utiliser des bananes plantains mûres ?","a":"Pour cette texture, il faut des plantains bien verts. Les mûrs deviennent tendres et sucrés à la cuisson."},{"q":"Comment éviter de les casser en les aplatissant ?","a":"Pressez-les encore tièdes entre deux feuilles de papier cuisson, progressivement, en laissant environ 8 mm d’épaisseur."},{"q":"Quand ajouter le hogao ?","a":"Servez-le tiède à part ou ajoutez-le au dernier moment. La sauce déposée trop tôt ramollit les galettes."},{"q":"Comment conserver et réchauffer les restes ?","a":"Gardez hogao et patacones séparément dans des boîtes fermées au réfrigérateur jusqu’à 3 jours. Réchauffez les disques au four à 200 °C et la sauce à part."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"e47b80ac-0999-580f-82ca-146c03bf17d3","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"it","slug":"patacones-colombiani-con-hogao","public_path":"/it/patacones-colombiani-con-hogao","source_url":null,"source_post_id":null,"title":"Patacones colombiani con hogao","excerpt":"Dischi di platano verde fritti due volte, con salsa colombiana tiepida di pomodoro e cipollotto.","summary":"I platani verdi si friggono una prima volta per ammorbidirli, si schiacciano e si friggono di nuovo finché diventano croccanti. Servi l’hogao di pomodoro e cipollotto tiepido a parte.","notes":"Scegli platani sodi e completamente verdi. Asciuga i pezzi prima di friggerli per ridurre gli schizzi. Usa un termometro, friggi in più riprese e non lasciare mai l’olio caldo incustodito. Non tutto l’olio di frittura viene consumato: la stima nutrizionale ipotizza che i 12 patacones ne assorbano 60 g, quantità non misurata. Metti salsa e patacones in frigorifero separatamente entro 2 ore e conservali fino a 3 giorni. Riscalda i dischi in forno a 200 °C e la salsa a parte. La formulazione non contiene ingredienti con latte o glutine; in caso di allergie controlla le etichette e la contaminazione crociata.","content_html":"<p>I platani verdi si friggono una prima volta per ammorbidirli, si schiacciano e si friggono di nuovo finché diventano croccanti. Servi l’hogao di pomodoro e cipollotto tiepido a parte.</p><p>Scegli platani sodi e completamente verdi. Asciuga i pezzi prima di friggerli per ridurre gli schizzi. Usa un termometro, friggi in più riprese e non lasciare mai l’olio caldo incustodito. Non tutto l’olio di frittura viene consumato: la stima nutrizionale ipotizza che i 12 patacones ne assorbano 60 g, quantità non misurata. Metti salsa e patacones in frigorifero separatamente entro 2 ore e conservali fino a 3 giorni. Riscalda i dischi in forno a 200 °C e la salsa a parte. La formulazione non contiene ingredienti con latte o glutine; in caso di allergie controlla le etichette e la contaminazione crociata.</p>","ingredients":[{"name":"platani verdi e sodi (circa 600 g di polpa sbucciata)","amount":"3","unit":"","group":"Per i patacones"},{"name":"olio di colza per friggere (non si consuma tutto)","amount":"750","unit":"ml","group":"Per i patacones"},{"name":"pomodori maturi","amount":"300","unit":"g","group":"Per l’hogao"},{"name":"cipollotti","amount":"120","unit":"g","group":"Per l’hogao"},{"name":"aglio","amount":"12","unit":"g","group":"Per l’hogao"},{"name":"olio di colza","amount":"15","unit":"g","group":"Per l’hogao"},{"name":"sale fino, diviso","amount":"6","unit":"g","group":"Per entrambi"}],"steps":[{"title":"Sbuccia e taglia i platani","content":"Sbuccia 3 platani completamente verdi e taglia ciascuno trasversalmente in 4 pezzi di circa 4 cm, per un totale di 12.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Patacones colombiani con hogao: Sbuccia e taglia i platani"},{"title":"Trita le verdure","content":"Trita finemente 300 g di pomodori, 120 g di cipollotti e 12 g di aglio; tienili separati.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Patacones colombiani con hogao: Trita le verdure"},{"title":"Rosola i cipollotti","content":"Scalda 15 g di olio di colza in padella a fuoco medio-basso. Cuoci cipollotti e aglio per 3 minuti senza farli dorare.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Patacones colombiani con hogao: Rosola i cipollotti"},{"title":"Fai restringere l’hogao","content":"Aggiungi i pomodori e 2 g di sale. Cuoci a fuoco basso per 12–15 minuti mescolando, finché i pomodori si disfano e la salsa si addensa.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Patacones colombiani con hogao: Fai restringere l’hogao"},{"title":"Friggi i pezzi una prima volta","content":"Scalda 2–3 cm di olio di colza in una padella profonda a circa 165–170 °C. Friggi i pezzi in più riprese per 4–5 minuti, finché sono morbidi ma non completamente dorati. Scola.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Patacones colombiani con hogao: Friggi i pezzi una prima volta"},{"title":"Schiaccia i platani","content":"Lascia intiepidire i pezzi per 2 minuti. Schiacciali uno alla volta tra due fogli di carta forno formando dischi spessi circa 8 mm, senza romperli.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Patacones colombiani con hogao: Schiaccia i platani"},{"title":"Friggi di nuovo i dischi","content":"Porta l’olio a circa 175–180 °C. Friggi i dischi in più riprese per 2–3 minuti per lato, finché sono dorati e croccanti. Scola e cospargi con i 4 g di sale rimasti.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Patacones colombiani con hogao: Friggi di nuovo i dischi"},{"title":"Servi con l’hogao","content":"Servi 3 patacones caldi a persona con l’hogao tiepido in una ciotola a parte. Aggiungi la salsa solo al momento di mangiare.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Patacones colombiani con hogao: Servi con l’hogao"}],"category":"Antipasti e aperitivi","course":"Antipasto","cuisine":"Colombiana","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Patacones colombiani con hogao"}],"video_urls":[],"keywords":["patacones con hogao","patacones colombiani","platano verde fritto","salsa colombiana al pomodoro"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 patacones con un quarto dell’hogao","method":"Somma dei nutrienti per 100 g × peso degli ingredienti / 100, divisa per quattro; si ipotizzano 600 g di polpa di platano verde, 300 g di pomodori, 120 g di cipollotti, 12 g di aglio, 15 g di olio nella salsa, 60 g di olio assorbito e 6 g di sale.","note":"Stima basata sulla formulazione. Il peso della polpa sbucciata e l’olio assorbito vanno misurati in una prova pratica; i valori per porzione possono variare notevolmente."},"seo":{"title":"Patacones colombiani con hogao | Manual de Cocina","description":"Patacones colombiani con hogao: platano verde fritto due volte e salsa di pomodoro e cipollotto. Ricetta illustrata in otto passaggi.","image_alt":"Patacones colombiani con hogao","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"Perché si friggono due volte?","a":"La prima frittura ammorbidisce il platano per schiacciarlo; la seconda rende il disco dorato e croccante."},{"q":"Posso usare platani maturi?","a":"Per questa consistenza servono platani completamente verdi. Quelli maturi diventano morbidi e dolci durante la frittura."},{"q":"Come evito che si rompano schiacciandoli?","a":"Schiacciali quando sono ancora tiepidi tra due fogli di carta forno, con pressione graduale, lasciandoli spessi circa 8 mm."},{"q":"Quando aggiungo l’hogao?","a":"Servilo tiepido a parte o aggiungilo appena prima di mangiare. Lasciarlo sopra troppo a lungo rende i dischi molli."},{"q":"Come conservo e riscaldo gli avanzi?","a":"Conserva hogao e patacones separati in contenitori chiusi in frigorifero fino a 3 giorni. Riscalda i dischi in forno a 200 °C e la salsa a parte."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"e09432be-34d3-52c5-8945-ae79fc9baa03","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"ja","slug":"パタコンとオガオ","public_path":"/ja/パタコンとオガオ","source_url":null,"source_post_id":null,"title":"コロンビアのパタコンとオガオ","excerpt":"青い調理用バナナを二度揚げしたパタコンに、トマトと青ねぎの温かいコロンビア風ソースを添えます。","summary":"青い調理用バナナをまず揚げて柔らかくし、押しつぶしてから再び揚げてカリッと仕上げます。トマトと青ねぎのオガオは別添えにし、食べる直前にかけます。","notes":"硬くて完全に青い調理用バナナを選びます。油はねを抑えるため、揚げる前に水気を拭き取ってください。温度計を使い、少量ずつ揚げ、熱い油から目を離さないでください。揚げ油の全量を食べるわけではありません。栄養価は12個で油60 gを吸収すると仮定していますが、実測値ではありません。パタコンとソースを別々の容器に入れ、2時間以内に冷蔵し、3日以内に食べてください。パタコンは200 °Cのオーブンで、ソースは別に温め直します。この材料構成に乳製品やグルテンを含む材料はありません。アレルギーがある場合は製品表示と交差接触を確認してください。","content_html":"<p>青い調理用バナナをまず揚げて柔らかくし、押しつぶしてから再び揚げてカリッと仕上げます。トマトと青ねぎのオガオは別添えにし、食べる直前にかけます。</p><p>硬くて完全に青い調理用バナナを選びます。油はねを抑えるため、揚げる前に水気を拭き取ってください。温度計を使い、少量ずつ揚げ、熱い油から目を離さないでください。揚げ油の全量を食べるわけではありません。栄養価は12個で油60 gを吸収すると仮定していますが、実測値ではありません。パタコンとソースを別々の容器に入れ、2時間以内に冷蔵し、3日以内に食べてください。パタコンは200 °Cのオーブンで、ソースは別に温め直します。この材料構成に乳製品やグルテンを含む材料はありません。アレルギーがある場合は製品表示と交差接触を確認してください。</p>","ingredients":[{"name":"硬い青い調理用バナナ（皮を除いた果肉約600 g）","amount":"3","unit":"本","group":"パタコン用"},{"name":"揚げ用キャノーラ油（全量は消費しない）","amount":"750","unit":"ml","group":"パタコン用"},{"name":"完熟トマト","amount":"300","unit":"g","group":"オガオ用"},{"name":"青ねぎ","amount":"120","unit":"g","group":"オガオ用"},{"name":"にんにく","amount":"12","unit":"g","group":"オガオ用"},{"name":"キャノーラ油","amount":"15","unit":"g","group":"オガオ用"},{"name":"細かい塩（分けて使用）","amount":"6","unit":"g","group":"両方に使用"}],"steps":[{"title":"調理用バナナをむいて切る","content":"完全に青い調理用バナナ3本の皮をむき、それぞれを長さ約4 cmの輪切りに4等分します。合計12個にします。","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"コロンビアのパタコンとオガオ: 調理用バナナをむいて切る"},{"title":"野菜を刻む","content":"トマト300 g、青ねぎ120 g、にんにく12 gを細かく刻み、それぞれ分けておきます。","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"コロンビアのパタコンとオガオ: 野菜を刻む"},{"title":"青ねぎを炒める","content":"フライパンにキャノーラ油15 gを入れて中弱火で温め、青ねぎとにんにくを焦がさず3分炒めます。","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"コロンビアのパタコンとオガオ: 青ねぎを炒める"},{"title":"オガオを煮詰める","content":"トマトと塩2 gを加えます。弱火で12〜15分かき混ぜながら煮て、トマトが崩れ、ソースにとろみがつくまで加熱します。","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"コロンビアのパタコンとオガオ: オガオを煮詰める"},{"title":"一度目の揚げ調理をする","content":"深めのフライパンにキャノーラ油を深さ2〜3 cmまで注ぎ、約165〜170 °Cに温めます。バナナを数回に分けて4〜5分揚げ、完全に色づく前の柔らかい状態で取り出し、油を切ります。","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"コロンビアのパタコンとオガオ: 一度目の揚げ調理をする"},{"title":"調理用バナナを押しつぶす","content":"2分ほど冷ました後、各片をオーブン用シート2枚ではさみ、割らないように厚さ約8 mmの円盤状に押しつぶします。","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"コロンビアのパタコンとオガオ: 調理用バナナを押しつぶす"},{"title":"円盤をもう一度揚げる","content":"油を約175〜180 °Cに上げます。円盤を数回に分け、片面2〜3分ずつ、黄金色でカリッとするまで揚げます。油を切り、残りの塩4 gをふります。","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"コロンビアのパタコンとオガオ: 円盤をもう一度揚げる"},{"title":"オガオを添えて盛る","content":"1人につき熱いパタコン3個を盛り、温かいオガオを別の器に入れます。カリッとした食感を保つため、食べる直前にソースをのせます。","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"コロンビアのパタコンとオガオ: オガオを添えて盛る"}],"category":"前菜・軽食","course":"前菜","cuisine":"コロンビア料理","difficulty":"簡単","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"コロンビアのパタコンとオガオ"}],"video_urls":[],"keywords":["パタコン オガオ","コロンビア パタコン","青い調理用バナナ 揚げ物","トマトソース"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"パタコン3個とオガオの4分の1量","method":"材料100 gあたりの栄養価×使用重量÷100を合計し、4人分で割った推定値。皮をむいた青い調理用バナナ600 g、トマト300 g、青ねぎ120 g、にんにく12 g、ソース用油15 g、吸収された揚げ油60 g、塩6 gを仮定。","note":"材料の配合から算出した概算です。皮をむいた果肉の重量と吸収された油の量は調理試験で測る必要があり、実際の1人分の値は大きく変わる場合があります。"},"seo":{"title":"コロンビアのパタコンとオガオ | Manual de Cocina","description":"青い調理用バナナを二度揚げして作るコロンビアのパタコン。トマトと青ねぎのオガオを添える、写真付き8ステップのレシピ。","image_alt":"コロンビアのパタコンとオガオ","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"なぜ二度揚げするのですか？","a":"一度目でバナナを柔らかくしてつぶしやすくし、二度目で円盤をこんがりカリッと仕上げます。"},{"q":"熟した調理用バナナでも作れますか？","a":"この食感には完全に青いものが必要です。熟したものは揚げると柔らかく甘くなります。"},{"q":"つぶすときに割れないコツは？","a":"まだ温かいうちにオーブン用シートではさみ、少しずつ圧力をかけ、厚さ約8 mmに仕上げます。"},{"q":"オガオはいつかけますか？","a":"温かいソースを別添えにするか、食べる直前にのせます。長くのせるとパタコンがしんなりします。"},{"q":"残りはどう保存して温め直しますか？","a":"ソースとパタコンを別々の密閉容器に入れ、冷蔵庫で3日以内に使います。パタコンは200 °Cのオーブンでカリッと温め、ソースは別に温めます。"}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0},{"id":"493db0b2-c05a-5447-b811-a675d3fd9df7","recipe_group_id":"2d311f01-3a8d-52fa-b900-8329ba2ddec8","language":"pt","slug":"patacones-com-hogao","public_path":"/pt/patacones-com-hogao","source_url":null,"source_post_id":null,"title":"Patacones colombianos com hogao","excerpt":"Banana-da-terra verde frita duas vezes com molho colombiano morno de tomate e cebolinha.","summary":"A banana-da-terra verde é frita uma vez para amaciar, achatada e frita novamente até ficar crocante. Sirva o hogao de tomate e cebolinha morno à parte para manter a crocância.","notes":"Escolha bananas-da-terra firmes e bem verdes. Seque os pedaços antes de fritar para reduzir respingos. Use termômetro, frite em levas e nunca deixe o óleo quente sem supervisão. O óleo da frigideira não é consumido por inteiro: o cálculo nutricional supõe que os 12 patacones absorvam 60 g, quantidade não medida. Leve os discos e o molho à geladeira, em recipientes separados, dentro de 2 horas e consuma em até 3 dias. Reaqueça os discos no forno a 200 °C e o molho separadamente. Esta formulação não contém ingredientes lácteos ou com glúten; em caso de alergias, confira rótulos e contaminação cruzada.","content_html":"<p>A banana-da-terra verde é frita uma vez para amaciar, achatada e frita novamente até ficar crocante. Sirva o hogao de tomate e cebolinha morno à parte para manter a crocância.</p><p>Escolha bananas-da-terra firmes e bem verdes. Seque os pedaços antes de fritar para reduzir respingos. Use termômetro, frite em levas e nunca deixe o óleo quente sem supervisão. O óleo da frigideira não é consumido por inteiro: o cálculo nutricional supõe que os 12 patacones absorvam 60 g, quantidade não medida. Leve os discos e o molho à geladeira, em recipientes separados, dentro de 2 horas e consuma em até 3 dias. Reaqueça os discos no forno a 200 °C e o molho separadamente. Esta formulação não contém ingredientes lácteos ou com glúten; em caso de alergias, confira rótulos e contaminação cruzada.</p>","ingredients":[{"name":"bananas-da-terra bem verdes (cerca de 600 g de polpa descascada)","amount":"3","unit":"unidades","group":"Para os patacones"},{"name":"óleo de canola para fritar (não é todo consumido)","amount":"750","unit":"ml","group":"Para os patacones"},{"name":"tomates maduros","amount":"300","unit":"g","group":"Para o hogao"},{"name":"cebolinha","amount":"120","unit":"g","group":"Para o hogao"},{"name":"alho","amount":"12","unit":"g","group":"Para o hogao"},{"name":"óleo de canola","amount":"15","unit":"g","group":"Para o hogao"},{"name":"sal fino, dividido","amount":"6","unit":"g","group":"Para ambos"}],"steps":[{"title":"Descasque e corte as bananas","content":"Descasque 3 bananas-da-terra bem verdes e corte cada uma em 4 pedaços transversais de cerca de 4 cm, totalizando 12 pedaços.","image_url":"/recetas/patacones-con-hogao/paso-01.webp","image_alt":"Patacones colombianos com hogao: Descasque e corte as bananas"},{"title":"Pique os vegetais","content":"Pique finamente 300 g de tomate, 120 g de cebolinha e 12 g de alho; mantenha-os separados.","image_url":"/recetas/patacones-con-hogao/paso-02.webp","image_alt":"Patacones colombianos com hogao: Pique os vegetais"},{"title":"Refogue a cebolinha","content":"Aqueça 15 g de óleo de canola em uma frigideira em fogo médio-baixo. Cozinhe a cebolinha e o alho por 3 minutos sem dourar.","image_url":"/recetas/patacones-con-hogao/paso-03.webp","image_alt":"Patacones colombianos com hogao: Refogue a cebolinha"},{"title":"Apure o hogao","content":"Acrescente o tomate e 2 g de sal. Cozinhe em fogo baixo por 12 a 15 minutos, mexendo, até o tomate desmanchar e o molho engrossar.","image_url":"/recetas/patacones-con-hogao/paso-04.webp","image_alt":"Patacones colombianos com hogao: Apure o hogao"},{"title":"Frite os pedaços pela primeira vez","content":"Aqueça óleo de canola suficiente para cobrir 2 a 3 cm de uma frigideira funda, a cerca de 165–170 °C. Frite os pedaços em levas por 4 a 5 minutos, até amolecerem sem dourar completamente. Escorra.","image_url":"/recetas/patacones-con-hogao/paso-05.webp","image_alt":"Patacones colombianos com hogao: Frite os pedaços pela primeira vez"},{"title":"Achate as bananas","content":"Deixe os pedaços amornarem por 2 minutos. Pressione cada um entre duas folhas de papel-manteiga até formar um disco de cerca de 8 mm, sem quebrá-lo.","image_url":"/recetas/patacones-con-hogao/paso-06.webp","image_alt":"Patacones colombianos com hogao: Achate as bananas"},{"title":"Frite os discos novamente","content":"Eleve o óleo a cerca de 175–180 °C. Frite os discos em levas por 2 a 3 minutos de cada lado, até ficarem dourados e crocantes. Escorra e polvilhe os 4 g de sal restantes.","image_url":"/recetas/patacones-con-hogao/paso-07.webp","image_alt":"Patacones colombianos com hogao: Frite os discos novamente"},{"title":"Sirva com hogao","content":"Sirva 3 patacones quentes por pessoa e o hogao morno em uma tigela separada. Coloque o molho só na hora de comer para preservar a crocância.","image_url":"/recetas/patacones-con-hogao/paso-08.webp","image_alt":"Patacones colombianos com hogao: Sirva com hogao"}],"category":"Entradas e petiscos","course":"Entrada","cuisine":"Colombiana","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":65,"servings":4,"image_url":"/recetas/patacones-con-hogao/portada.webp","gallery":[{"url":"/recetas/patacones-con-hogao/portada.webp","alt":"Patacones colombianos com hogao"}],"video_urls":[],"keywords":["patacones com hogao","patacones colombianos","banana-da-terra verde frita","molho colombiano de tomate"],"nutrition":{"calories":421,"protein_g":3.3,"carbs_g":61.1,"fat_g":19.1,"saturated_fat_g":1.6,"fiber_g":5.0,"sugar_g":6.1,"sodium_mg":593.0,"estimated":true,"source":"USDA FoodData Central — FDC 168215 and SR Legacy April 2018","source_url":"https://fdc.nal.usda.gov/","serving_size":"3 patacones com um quarto do hogao","method":"Soma dos nutrientes por 100 g × peso dos ingredientes / 100, dividida por quatro; considera 600 g de polpa de banana-da-terra verde, 300 g de tomate, 120 g de cebolinha, 12 g de alho, 15 g de óleo no molho, 60 g de óleo absorvido na fritura e 6 g de sal.","note":"Estimativa baseada na formulação. O peso da polpa descascada e o óleo absorvido precisam ser medidos em teste prático; os valores reais por porção podem variar bastante."},"seo":{"title":"Patacones colombianos com hogao | Manual de Cocina","description":"Como fazer patacones colombianos com hogao: banana-da-terra verde frita duas vezes e molho de tomate e cebolinha, em oito passos ilustrados.","image_alt":"Patacones colombianos com hogao","image_variants":["/recetas/patacones-con-hogao/portada-1x1.webp","/recetas/patacones-con-hogao/portada-4x3.webp","/recetas/patacones-con-hogao/portada-16x9.webp"],"faq":[{"q":"Por que fritar os patacones duas vezes?","a":"A primeira fritura amacia a banana para poder achatá-la; a segunda deixa o disco dourado e crocante."},{"q":"Posso usar banana-da-terra madura?","a":"Para esta textura, use banana-da-terra bem verde. A madura amolece e fica doce ao fritar."},{"q":"Como evitar que quebrem ao achatar?","a":"Pressione os pedaços ainda mornos entre folhas de papel-manteiga, gradualmente, sem deixar os discos finos demais: cerca de 8 mm."},{"q":"Quando acrescentar o hogao?","a":"Sirva morno à parte ou coloque na hora de comer. Se ficar sobre os patacones por muito tempo, eles perdem a crocância."},{"q":"Como guardar e reaquecer?","a":"Guarde molho e patacones separadamente em recipientes fechados na geladeira por até 3 dias. Reaqueça os discos no forno a 200 °C e o hogao à parte."}]},"published":true,"published_at":"2026-10-14T01:00:39+00:00","ready_at":"2026-10-14T01:00:39+00:00","editorial_status":"published","rating_count":0,"rating_sum":0}]$records$::jsonb;
 g constant uuid := '2d311f01-3a8d-52fa-b900-8329ba2ddec8';
 n int;
BEGIN
 IF jsonb_array_length(j)<>7 OR (SELECT count(DISTINCT x->>'language') FROM jsonb_array_elements(j) x)<>7 OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j) x)<>7 THEN RAISE EXCEPTION 'Expected seven unique language routes'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(j) x WHERE jsonb_array_length(x->'steps')=8 AND jsonb_array_length(x->'seo'->'faq')=5 AND x->>'recipe_group_id'=g::text AND x->>'published'='true')<>7 THEN RAISE EXCEPTION 'Incomplete patacones records'; END IF;
 IF EXISTS(SELECT 1 FROM public.recipes WHERE recipe_group_id=g OR id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(j) x)) THEN RAISE EXCEPTION 'Patacones group or ID already exists; no mutation'; END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(j) x ON (r.language=x->>'language' AND r.slug=x->>'slug') OR r.public_path=x->>'public_path') THEN RAISE EXCEPTION 'Recipe route collision'; END IF;
 IF EXISTS(SELECT 1 FROM public.content_pages c JOIN jsonb_array_elements(j) x ON c.public_path=x->>'public_path') THEN RAISE EXCEPTION 'Content page route collision'; END IF;
 IF EXISTS(SELECT 1 FROM public.content_redirects c JOIN jsonb_array_elements(j) x ON c.source_path=x->>'public_path') THEN RAISE EXCEPTION 'Redirect route collision'; END IF;
 INSERT INTO public.recipes (id,recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,prep_time_minutes,cook_time_minutes,servings,image_url,published,published_at,content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,nutrition,gallery,video_urls,seo,source_post_id,source_url,public_path,editorial_status,ready_at,rating_count,rating_sum)
 SELECT id,recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,prep_time_minutes,cook_time_minutes,servings,image_url,published,published_at,content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,nutrition,gallery,video_urls,seo,source_post_id,source_url,public_path,editorial_status,ready_at,rating_count,rating_sum FROM jsonb_populate_recordset(NULL::public.recipes,j);
 GET DIAGNOSTICS n = ROW_COUNT;
 IF n<>7 THEN RAISE EXCEPTION 'Expected 7 inserts, got %',n; END IF;
END $patacones$;
